--- a/secp256r1/src/field.rs
+++ b/secp256r1/src/field.rs
@@ -327,11 +327,17 @@
-        let (difference, borrow) = sub_limbs(a, n);
-        if borrow != 0 {
-            // a < n: swap them, so the new a is n - a = -difference.
-            if (a[0] & 3) == 3 && (n[0] & 3) == 3 {
-                negate = !negate;
-            }
-            n = a;
-            a = sub_limbs([0; 4], difference).0;
-        } else {
-            a = difference;
-        }
+        // The top limbs almost always decide the comparison.
+        let a_below_n = if a[3] != n[3] {
+            a[3] < n[3]
+        } else {
+            !ge_limbs(a, n)
+        };
+        if a_below_n {
+            // a < n: swap them, so the new a is n - a.
+            if (a[0] & 3) == 3 && (n[0] & 3) == 3 {
+                negate = !negate;
+            }
+            let old_n = n;
+            n = a;
+            a = sub_limbs(old_n, a).0;
+        } else {
+            a = sub_limbs(a, n).0;
+        }

